// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title LegacyVault
 * @dev Inheritance vault (dead man's switch): Owner deposits assets, adds heirs with proportional shares.
 *      Heirs can claim their share if owner is inactive for a set period (30-365 days).
 *      Supports both native ETH and ERC20 tokens with separate balance tracking.
 */
contract LegacyVault is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============= Constants =============
    uint256 private constant MIN_INACTIVITY_PERIOD = 30 days;
    uint256 private constant MAX_INACTIVITY_PERIOD = 365 days;
    uint256 private constant MAX_HEIRS = 50;

    // ============= State Variables =============
    address public owner;
    uint256 public inactivityPeriod;
    uint256 public lastActivity;
    bool public initialized;

    // Native ETH balance
    uint256 public ethBalance;

    // ERC20 token balances: token => balance
    mapping(address => uint256) public tokenBalances;

    // Heirs management: heir => HeirInfo
    struct HeirInfo {
        uint256 points;
        bool claimed;
    }

    mapping(address => HeirInfo) public heirs;
    address[] public heirsList;
    mapping(address => uint256) public heirIndex; // Index in heirsList (1-based, 0 = not exist)

    uint256 public totalPoints;

    // ============= Events =============
    event Initialized(uint256 inactivityPeriod);
    event DepositETH(address indexed depositor, uint256 amount, uint256 newBalance);
    event WithdrawETH(address indexed owner, uint256 amount, uint256 newBalance);
    event DepositERC20(address indexed token, address indexed depositor, uint256 amount, uint256 newBalance);
    event WithdrawERC20(address indexed token, address indexed owner, uint256 amount, uint256 newBalance);
    event HeirAdded(address indexed heir, uint256 points, uint256 totalPoints);
    event HeirRemoved(address indexed heir, uint256 points, uint256 totalPoints);
    event InactivityPeriodSet(uint256 newPeriod);
    event Claimed(address indexed heir, address indexed token, uint256 amount);

    // ============= Modifiers =============
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyInitialized() {
        require(initialized, "Vault not initialized");
        _;
    }

    // ============= Constructor =============
    constructor() {
        owner = msg.sender;
    }

    // ============= Initialization =============
    /**
     * @dev Owner must explicitly initialize the vault with an inactivity period.
     * @param _inactivityPeriod Inactivity period in seconds (30-365 days).
     */
    function initialize(uint256 _inactivityPeriod) external onlyOwner {
        require(!initialized, "Already initialized");
        require(
            _inactivityPeriod >= MIN_INACTIVITY_PERIOD && _inactivityPeriod <= MAX_INACTIVITY_PERIOD,
            "Invalid inactivity period"
        );

        inactivityPeriod = _inactivityPeriod;
        lastActivity = block.timestamp;
        initialized = true;

        emit Initialized(_inactivityPeriod);
    }

    // ============= Deposit Functions =============
    /**
     * @dev Deposit native ETH to the vault. Resets lastActivity.
     */
    function depositETH() external payable onlyOwner onlyInitialized {
        require(msg.value > 0, "Deposit amount must be > 0");

        ethBalance += msg.value;
        lastActivity = block.timestamp;

        emit DepositETH(msg.sender, msg.value, ethBalance);
    }

    /**
     * @dev Deposit ERC20 tokens to the vault. Resets lastActivity.
     * @param token ERC20 token address.
     * @param amount Amount to deposit.
     */
    function depositERC20(address token, uint256 amount) external onlyOwner onlyInitialized {
        require(token != address(0), "Invalid token");
        require(amount > 0, "Deposit amount must be > 0");

        // Transfer tokens from sender to contract (Checks-Effects-Interactions)
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        tokenBalances[token] += amount;
        lastActivity = block.timestamp;

        emit DepositERC20(token, msg.sender, amount, tokenBalances[token]);
    }

    // ============= Withdrawal Functions =============
    /**
     * @dev Owner withdraws ETH. Only owner can withdraw while active. Resets lastActivity.
     * @param amount Amount to withdraw.
     */
    function withdrawETH(uint256 amount) external onlyOwner onlyInitialized {
        require(amount > 0, "Withdraw amount must be > 0");
        require(amount <= ethBalance, "Insufficient ETH balance");

        ethBalance -= amount;
        lastActivity = block.timestamp;

        // Interaction: Send ETH
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "ETH transfer failed");

        emit WithdrawETH(msg.sender, amount, ethBalance);
    }

    /**
     * @dev Owner withdraws ERC20 tokens. Only owner can withdraw while active. Resets lastActivity.
     * @param token ERC20 token address.
     * @param amount Amount to withdraw.
     */
    function withdrawERC20(address token, uint256 amount) external onlyOwner onlyInitialized {
        require(token != address(0), "Invalid token");
        require(amount > 0, "Withdraw amount must be > 0");
        require(amount <= tokenBalances[token], "Insufficient token balance");

        tokenBalances[token] -= amount;
        lastActivity = block.timestamp;

        // Interaction: Send tokens
        IERC20(token).safeTransfer(msg.sender, amount);

        emit WithdrawERC20(token, msg.sender, amount, tokenBalances[token]);
    }

    // ============= Heir Management =============
    /**
     * @dev Add an heir with a specific point allocation (proportional share). Resets lastActivity.
     * @param heir Heir address.
     * @param points Points for proportional share (relative to totalPoints).
     */
    function addHeir(address heir, uint256 points) external onlyOwner onlyInitialized {
        require(heir != address(0), "Invalid heir");
        require(heir != owner, "Owner cannot be an heir");
        require(points > 0, "Points must be > 0");
        require(heirsList.length < MAX_HEIRS, "Max heirs reached");

        // If heir already exists, update points
        if (heirIndex[heir] != 0) {
            uint256 oldPoints = heirs[heir].points;
            heirs[heir].points = points;
            totalPoints = totalPoints - oldPoints + points;
        } else {
            // Add new heir
            heirs[heir] = HeirInfo({points: points, claimed: false});
            heirIndex[heir] = heirsList.length + 1; // 1-based index
            heirsList.push(heir);
            totalPoints += points;
        }

        lastActivity = block.timestamp;

        emit HeirAdded(heir, points, totalPoints);
    }

    /**
     * @dev Remove an heir. Resets lastActivity. Uses swap-pop for O(1) removal.
     * @param heir Heir address.
     */
    function removeHeir(address heir) external onlyOwner onlyInitialized {
        require(heirIndex[heir] != 0, "Heir not found");

        uint256 points = heirs[heir].points;
        uint256 index = heirIndex[heir] - 1; // Convert to 0-based

        // Swap with last heir and pop
        address lastHeir = heirsList[heirsList.length - 1];
        heirsList[index] = lastHeir;
        heirIndex[lastHeir] = index + 1; // Update new index (1-based)

        heirsList.pop();
        delete heirs[heir];
        delete heirIndex[heir];

        totalPoints -= points;
        lastActivity = block.timestamp;

        emit HeirRemoved(heir, points, totalPoints);
    }

    // ============= Inactivity Period Management =============
    /**
     * @dev Owner sets a new inactivity period. Resets lastActivity.
     * @param _inactivityPeriod New inactivity period in seconds (30-365 days).
     */
    function setInactivityPeriod(uint256 _inactivityPeriod) external onlyOwner onlyInitialized {
        require(
            _inactivityPeriod >= MIN_INACTIVITY_PERIOD && _inactivityPeriod <= MAX_INACTIVITY_PERIOD,
            "Invalid inactivity period"
        );

        inactivityPeriod = _inactivityPeriod;
        lastActivity = block.timestamp;

        emit InactivityPeriodSet(_inactivityPeriod);
    }

    // ============= Claim Functions =============
    /**
     * @dev Heir claims their share of native ETH. Can only claim if owner is inactive and hasn't claimed yet.
     *      Uses Checks-Effects-Interactions pattern with ReentrancyGuard.
     */
    function claimETH() external nonReentrant {
        require(heirIndex[msg.sender] != 0, "Not an heir");
        HeirInfo storage heirInfo = heirs[msg.sender];
        require(!heirInfo.claimed, "Already claimed");
        require(isOwnerInactive(), "Owner is still active");

        // Calculate heir's share: (heirPoints / totalPoints) * ethBalance
        uint256 share = (heirInfo.points * ethBalance) / totalPoints;
        require(share > 0, "No share available");

        // Effects: Mark as claimed before interaction
        heirInfo.claimed = true;
        ethBalance -= share;

        // Interaction: Send ETH
        (bool success, ) = msg.sender.call{value: share}("");
        require(success, "ETH transfer failed");

        emit Claimed(msg.sender, address(0), share);
    }

    /**
     * @dev Heir claims their share of a specific ERC20 token. Can only claim if owner is inactive and hasn't claimed yet.
     *      Uses Checks-Effects-Interactions pattern with ReentrancyGuard.
     * @param token ERC20 token address.
     */
    function claimERC20(address token) external nonReentrant {
        require(token != address(0), "Invalid token");
        require(heirIndex[msg.sender] != 0, "Not an heir");
        HeirInfo storage heirInfo = heirs[msg.sender];
        require(!heirInfo.claimed, "Already claimed");
        require(isOwnerInactive(), "Owner is still active");

        uint256 balance = tokenBalances[token];
        require(balance > 0, "No token balance available");

        // Calculate heir's share: (heirPoints / totalPoints) * tokenBalance
        uint256 share = (heirInfo.points * balance) / totalPoints;
        require(share > 0, "No share available");

        // Effects: Reduce balance before interaction
        tokenBalances[token] -= share;

        // Interaction: Send tokens
        IERC20(token).safeTransfer(msg.sender, share);

        emit Claimed(msg.sender, token, share);
    }

    // ============= View Functions =============
    /**
     * @dev Check if owner is inactive.
     * @return True if current time >= lastActivity + inactivityPeriod.
     */
    function isOwnerInactive() public view returns (bool) {
        return block.timestamp >= lastActivity + inactivityPeriod;
    }

    /**
     * @dev Get the number of heirs.
     */
    function getHeirsCount() external view returns (uint256) {
        return heirsList.length;
    }

    /**
     * @dev Get heir at a specific index.
     * @param index Index in heirsList (0-based).
     */
    function getHeirAt(uint256 index) external view returns (address) {
        require(index < heirsList.length, "Index out of bounds");
        return heirsList[index];
    }

    /**
     * @dev Get all heirs.
     */
    function getAllHeirs() external view returns (address[] memory) {
        return heirsList;
    }

    /**
     * @dev Get heir info (points and claimed status).
     * @param heir Heir address.
     */
    function getHeirInfo(address heir) external view returns (uint256 points, bool claimed) {
        HeirInfo storage heirInfo = heirs[heir];
        return (heirInfo.points, heirInfo.claimed);
    }

    /**
     * @dev Get heir's share percentage (points / totalPoints) as basis points (0-10000).
     * @param heir Heir address.
     */
    function getHeirShareBP(address heir) external view returns (uint256) {
        if (totalPoints == 0) return 0;
        return (heirs[heir].points * 10000) / totalPoints;
    }

    /**
     * @dev Get heir's current claimable ETH amount.
     * @param heir Heir address.
     */
    function getClaimableETH(address heir) external view returns (uint256) {
        if (totalPoints == 0 || heirIndex[heir] == 0) return 0;
        return (heirs[heir].points * ethBalance) / totalPoints;
    }

    /**
     * @dev Get heir's current claimable ERC20 amount.
     * @param heir Heir address.
     * @param token ERC20 token address.
     */
    function getClaimableERC20(address heir, address token) external view returns (uint256) {
        if (totalPoints == 0 || heirIndex[heir] == 0) return 0;
        uint256 balance = tokenBalances[token];
        return (heirs[heir].points * balance) / totalPoints;
    }

    /**
     * @dev Get time until owner is considered inactive.
     * @return Remaining seconds, or 0 if already inactive.
     */
    function getTimeUntilInactive() external view returns (uint256) {
        uint256 deadline = lastActivity + inactivityPeriod;
        if (block.timestamp >= deadline) return 0;
        return deadline - block.timestamp;
    }

    // ============= Receive ETH =============
    /**
     * @dev Allow contract to receive ETH directly. Updates ethBalance and lastActivity.
     */
    receive() external payable onlyOwner onlyInitialized {
        ethBalance += msg.value;
        lastActivity = block.timestamp;
        emit DepositETH(msg.sender, msg.value, ethBalance);
    }
}

